def bellmanFord_max(n: int, edges: list[tuple[int, int, int]], s: int, t: int) -> int:
    # create path_length, path_length as a dict, with each key-value pair representing
    #  the shortest path length and the previous vertex of each vertex
    path_length = {i: (float('inf'), None) for i in range(n)}
    path_length[s] = (0, None)

    # iterate
    for i in range(n):
        for u, v, w in edges:
            # update path_lengths
            # 
            if path_length[u][0] == float('inf'):
                continue

            if path_length[u][0] - w < path_length[v][0]:
                path_length[v] = (path_length[u][0] - w, u)

    return path_length[t][0]


