def solve(n: int, edges: list[tuple[int, int, int]], s: int, t: int) -> int:
    edges_dict = {i: [] for i in range(n)}
    for u, v, w in edges:
        edges_dict[u].append((v, w))
    distances = [-1] * n
    distances[s] = 0
    queue = [(0, s)]
    while queue:
        distance, current = min(queue, key=lambda x: x[0])
        queue.remove((distance, current))
        if distance > distances[current]:
            continue
        for neighbor, weight in edges_dict[current]:
            new_distance = distance + weight
            if new_distance < distances[neighbor]:
                distances[neighbor] = new_distance
                queue.append((new_distance, neighbor))
    return distances[t]

